"""Court, prosecution, defense, assistants and experts, with historical guards."""
import json,sys
from pathlib import Path
CPP='https://www.planalto.gov.br/ccivil_03/decreto-lei/del3689compilado.htm'
CF='https://www.planalto.gov.br/ccivil_03/constituicao/constituicao.htm'
ADPF='https://portal.stf.jus.br/processos/listarProcessos.asp?classe=ADPF&numeroProcesso=395'
DEF='https://www.planalto.gov.br/ccivil_03/_ato2023-2026/2023/lei/l14752.htm'
CC='https://www.planalto.gov.br/ccivil_03/leis/2002/l10406compilada.htm'
CUR='https://www.stj.jus.br/websecstj/cgi/revista/REJ.cgi/ITA?CodOrgaoJgdr=&SeqCgrmaSessao=&dt=20150211&formato=PDF&nreg=201400285520&salvar=false&seq=1379594&tipo=0'
rows={}
def add(n,s,p,a,c,v,q,t,d,links=()):
 rows['art-'+str(n)]=dict(simples=s,pontos=p,atencao=[a],exemplo=c+' Variação: '+v,prova=q,termos=[dict(termo=t,significado=d)],remissoes=[CPP,*links])
add(251,'Juiz preserva regularidade e ordem dos atos, podendo requisitar força pública quando necessária.', ['Poder de organização não substitui acusação.', 'Medidas devem ser proporcionais e respeitar defesa.'], 'Manter ordem não autoriza calar defesa legítima ou investigar como parte.', 'Tumulto concreto exige medida adequada para retomar audiência.', 'Discordância jurídica respeitosa da defesa não justifica uso de força.', ['Pode requisitar força para preservar ordem? Sim.', 'Pode substituir acusação por essa regra? Não.'], 'Direção processual','Organização legítima dos atos judiciais.')
add(252,'Impedimento afasta juiz por vínculos objetivos expressamente previstos no processo.', ['Cônjuge ou parente até terceiro grau em funções enumeradas.', 'O próprio juiz anteriormente nessas funções ou como testemunha.', 'Atuação como juiz de outra instância com pronunciamento sobre a questão.', 'Interesse direto ou condição de parte própria ou dos familiares abrangidos.'], 'Não confundir grau de parentesco com grau recursal; nem presumir que qualquer ato anterior na mesma instância gera este impedimento.', 'Juiz não julga causa em que seu irmão atuou como defensor.', 'Atuação judicial anterior deve ser enquadrada na hipótese específica, não em impedimento inventado.', ['As hipóteses abrangem parentes até terceiro grau? Sim.', 'Toda decisão anterior na mesma instância satisfaz o inciso III? Não.'], 'Impedimento','Vínculo objetivo que impede jurisdição no feito.')
add(253,'Juízes parentes até terceiro grau não podem atuar juntos no mesmo processo em órgão coletivo.', ['Abrange consanguinidade e afinidade, linha reta ou colateral.', 'Vedação concerne ao mesmo processo no juízo coletivo.'], 'Não confundir esta regra entre julgadores com parentesco entre juiz e parte.', 'Dois irmãos não compõem o colegiado para julgar a mesma causa.', 'Ausência de parentesco entre julgadores não elimina outros impedimentos próprios.', ['A regra trata de parentesco entre julgadores? Sim.', 'Exclui análise de outros impedimentos? Não.'], 'Colegiado imparcial','Composição sem o parentesco vedado.')
add(254,'Suspeição trata de vínculos e situações que comprometem imparcialidade nas hipóteses enumeradas.', ['Amizade íntima ou inimizade capital.', 'Processo por fato análogo com controvérsia criminal na hipótese do inciso II.', 'Demanda a ser julgada por parte envolvendo juiz ou familiares abrangidos.', 'Aconselhamento de parte; crédito, débito, tutela ou curatela.', 'Vínculo societário com sociedade interessada.'], 'Conhecimento social superficial não equivale automaticamente a amizade íntima; identificar fatos e hipótese legal.', 'Juiz é credor de uma parte e comunica suspeição.', 'Só conhecer profissionalmente advogado não basta, sem circunstância legal pertinente.', ['Aconselhar parte pode gerar suspeição? Sim.', 'Qualquer contato social é amizade íntima? Não.'], 'Suspeição','Comprometimento da imparcialidade nas situações legais.')
add(255,'Fim do casamento pode cessar afinidade relevante ao impedimento ou suspeição, com exceções expressas.', ['Se há descendentes, a cessação prevista não ocorre.', 'Mesmo sem descendentes, não julga causa de sogro, padrasto, cunhado, genro ou enteado previstos como parte.'], 'Dissolução do casamento não apaga automaticamente todas as hipóteses de afastamento.', 'Mesmo após casamento dissolvido sem filhos, juiz não atua em processo de antigo cunhado como parte.', 'Existindo descendentes, não aplicar a regra geral de cessação como se fossem inexistentes.', ['Dissolução sempre elimina afastamento? Não.', 'O artigo conserva exceções mesmo sem descendentes? Sim.'], 'Afinidade residual','Vínculo relevante mantido nas hipóteses expressas.')
add(256,'Parte não pode fabricar suspeição por insultar juiz ou provocar deliberadamente sua causa.', ['Exige provocação intencional na hipótese legal.', 'Causa real independente de suspeição continua sujeita a análise.'], 'A regra não imuniza juiz contra motivos de suspeição efetivamente existentes.', 'Parte insulta juiz para tentar escolher outro julgador; isso não cria a suspeição pretendida.', 'Vínculo real preexistente de interesse deve ser analisado independentemente da provocação.', ['Injúria estratégica cria suspeição válida? Não.', 'Causa independente deixa de ser analisada? Não.'], 'Suspeição provocada','Tentativa artificial de afastar julgador.')
add(257,'Ministério Público promove privativamente ação penal pública e fiscaliza execução da lei.', ['Ação pública é sua atribuição prevista.', 'Fiscalização exige observar legalidade, inclusive garantias do acusado.', 'Distinguir ação privada e subsidiária nos requisitos próprios.'], 'Privatividade da ação pública não elimina ação privada subsidiária constitucional na inércia legal.', 'MP oferece denúncia quando presentes requisitos e também controla legalidade.', 'Ausência de base para acusar não autoriza denúncia por simples dever de acusação.', ['Também fiscaliza execução da lei? Sim.', 'Deve acusar sem justa causa? Não.'], 'Funções do MP','Promoção da ação pública e fiscalização jurídica.',[CF])
add(258,'Membro do MP se afasta por parentesco com juiz ou partes nos limites legais e por impedimento ou suspeição aplicáveis.', ['Cônjuge e parentes até terceiro grau, consanguíneos ou afins.', 'Regras do juiz se estendem naquilo que for aplicável.'], 'Não importar hipóteses incompatíveis de forma automática; nem ignorar vínculo com juiz.', 'Promotor não atua em processo de seu irmão como parte.', 'A análise alcança também parentesco vedado com o juiz da causa.', ['O parentesco relevante pode ser com o juiz? Sim.', 'Toda regra judicial se aplica sem adaptação? Não.'], 'Imparcialidade institucional','Afastamento do membro do MP nas situações legais.')
add(259,'Nome ou qualificação desconhecidos não retardam a ação quando identidade física é certa; descoberta posterior permite retificação.', ['Exige certeza sobre a pessoa física processada.', 'Retificação por termo em processo, julgamento ou execução.', 'Atos anteriores não perdem validade apenas pela correção.'], 'Não confundir nome incerto com dúvida sobre qual pessoa cometeu o fato.', 'Réu fisicamente identificado usa nome falso; nome verdadeiro é corrigido depois.', 'Se há dúvida sobre a própria pessoa, o artigo não sana acusação de indivíduo errado.', ['Nome desconhecido sempre paralisa ação? Não.', 'Identidade física certa é requisito? Sim.'], 'Identidade física','Certeza da pessoa, distinta de seus dados nominais.')
add(260,'Condução coercitiva para interrogatório de acusado ou investigado é incompatível com a Constituição, conforme ADPFs 395 e 444.', ['STF em 2018 afastou a expressão para o interrogatório.', 'Não transportar conclusão automaticamente para testemunha ou perito: regras próprias.', 'Outros atos envolvendo acusado exigem análise específica, necessidade e garantias.', 'Mandado nos atos juridicamente admitidos observa requisitos próprios.'], 'Falta ao interrogatório não legitima levar à força para obter respostas. A decisão preservou interrogatórios anteriores ao julgamento nos termos da modulação.', 'Réu não comparece para ser interrogado; não se ordena condução para obrigá-lo a depor.', 'Reconhecimento ou identificação têm disciplina distinta e não autorizam interrogatório coercitivo disfarçado.', ['Pode conduzir acusado para interrogatório após ausência? Não.', 'A decisão se estende mecanicamente a toda testemunha? Não.'], 'Não autoincriminação','Garantia que impede interrogatório coercitivo.',[ADPF])
add(261,'Todo acusado precisa de defensor, mesmo ausente ou foragido; defesa pública ou dativa deve apresentar manifestação fundamentada.', ['Defesa técnica indispensável.', 'Não basta presença formal sem atuação fundamentada prevista.', 'Ausência pessoal não elimina assistência técnica.'], 'Foragido não perde direito à defesa.', 'Réu ausente continua representado por defensor nos atos processuais.', 'Nomeação meramente nominal não substitui defesa técnica efetiva.', ['Foragido pode ser julgado sem defensor? Não.', 'Defesa dativa deve ser fundamentada? Sim.'], 'Defesa técnica','Assistência jurídica indispensável.')
add(262,'A expressão histórica acusado menor não impõe curador apenas porque réu tem entre 18 e 21 anos após maioridade civil aos 18.', ['Integrar Código Civil e entendimento do STJ.', 'Curadoria por incapacidade ou incidente específico possui outro fundamento.'], 'Não restaurar exigência etária superada; não confundir com incidente de insanidade.', 'Réu de 19 anos tem defensor, sem curador exigido só por idade.', 'Incidente de insanidade pode demandar curador por regra própria, independentemente deste antigo fundamento.', ['Idade de 19 anos exige curador automaticamente? Não.', 'Curadoria por outra causa possui regras próprias? Sim.'], 'Curadoria por fundamento próprio','Proteção fundada em hipótese atual, não antiga menoridade civil.',[CC,CUR])
add(263,'Sem defensor constituído, juiz nomeia defesa, preservando direito de escolha posterior ou autodefesa técnica se habilitado.', ['Escolha de defensor de confiança a qualquer tempo.', 'Autodefesa técnica exige habilitação.', 'Acusado não pobre paga honorários dativos arbitrados nos termos legais.'], 'Saber argumentar não é habilitação profissional para dispensar defensor técnico.', 'Juiz nomeia dativo e réu depois constitui advogado de confiança.', 'Réu sem habilitação não substitui defesa técnica apenas por querer defender-se sozinho.', ['Pode escolher outro defensor depois? Sim.', 'Qualquer réu pode dispensar técnica por autodefesa? Não.'], 'Defensor nomeado','Assistência designada quando não há constituição.')
add(264,'Nomeação para defesa exige patrocínio salvo motivo relevante; a multa em mil-réis é redação histórica, não valor monetário atual certificado.', ['Examinar motivo relevante para recusa.', 'Não inventar conversão de moeda antiga.', 'Distinguir nomeação desta regra e abandono do art. 265 atualizado.'], 'Não ensinar multa de mil-réis como cobrança atual nem restaurar antiga multa do art. 265 por analogia.', 'Advogado comunica razão relevante que inviabiliza aceitar nomeação.', 'Ausência de justificativa demanda análise do regime aplicável, sem conversão automática da antiga moeda.', ['Motivo relevante pode justificar recusa? Sim.', 'Pode converter mil-réis por conta própria em multa atual? Não.'], 'Encargo de defesa','Nomeação sujeita a análise de escusa e regime pertinente.')
add(265,'Lei 14.752/2023 prevê infração disciplinar por abandono sem justo motivo previamente comunicado, com preservação da defesa do acusado.', ['Caput atual: responsabilidade perante órgão correicional, sem repetir antiga multa judicial.', 'Ausência justificada pode adiar audiência; impedimento deve ser provado até abertura.', 'Sem prova, nomear substituto para o ato em vez de deixar acusado indefeso.', 'Abandono: intimar para novo defensor; se não localizado, nomear público ou dativo.'], 'Mudança de 2023 não permite processo sem defesa nem substituição automática de toda recusa justificada por abandono.', 'Defensor comunica e comprova impedimento; juiz aprecia adiamento.', 'Abandono exige garantir novo defensor e apuração disciplinar pelo órgão competente.', ['A redação atual repete a antiga multa do caput? Não.', 'Réu não localizado fica sem defensor após abandono? Não.'], 'Abandono e continuidade','Responsabilização com manutenção da defesa técnica.',[DEF])
add(266,'Indicação do defensor pelo acusado no interrogatório dispensa instrumento de mandato nessa hipótese.', ['Indicação deve constar do ato.', 'Dispensa específica não elimina habilitação nem regras de representação dos demais casos.'], 'Não concluir que nenhuma constituição de advogado exige formalização em qualquer contexto.', 'Réu indica advogado habilitado durante interrogatório e a indicação é registrada.', 'Em outro contexto, conferir forma aplicável, sem generalizar a exceção.', ['No interrogatório a indicação pode dispensar procuração? Sim.', 'A exceção vale indiscriminadamente em todo contexto? Não.'], 'Indicação no interrogatório','Constituição pela manifestação registrada no ato.')
add(267,'Parentes do juiz não atuam como defensores nas condições remetidas ao art. 252.', ['Integração com limites e vínculos do art. 252.', 'Proteger imparcialidade da atuação judicial.'], 'Não criar grau de parentesco diferente do dispositivo referido.', 'Irmão do juiz não exerce defesa naquela causa.', 'A verificação considera também afinidade e hipóteses expressas, não só sobrenome semelhante.', ['O artigo remete ao 252? Sim.', 'Mesmo sobrenome prova automaticamente parentesco vedado? Não.'], 'Defesa e parentesco','Vedação integrada às hipóteses de imparcialidade.')
add(268,'Ofendido, representante legal ou sucessores previstos podem intervir como assistente do MP na ação pública.', ['Legitimação remete ao art. 31 na falta do ofendido.', 'Não substitui titularidade da ação pública.', 'Exige admissão no processo.'], 'Assistente de acusação não é sinônimo de autor de ação privada.', 'Vítima pede admissão como assistente em ação pública.', 'Falta da vítima exige conferir legitimado do art. 31, sem aceitar qualquer interessado.', ['Pode intervir vítima como assistente? Sim.', 'Qualquer pessoa interessada tem legitimidade? Não.'], 'Assistência da acusação','Intervenção do legitimado ao lado do MP.')
add(269,'Assistente pode ser admitido antes do trânsito em julgado e recebe processo no estado em que estiver.', ['Admissão não se limita ao começo da instrução.', 'Não reabrir fases automaticamente por ingresso tardio.'], 'Intervenção posterior não garante repetição de atos válidos já praticados.', 'Vítima pede admissão após instrução, antes do trânsito.', 'Ingresso não obriga refazer todos os depoimentos.', ['Pode ingressar antes do trânsito mesmo em fase avançada? Sim.', 'Recebe causa desde o início com repetição automática? Não.'], 'Ingresso do assistente','Admissão no estágio processual existente.')
add(270,'Corréu no mesmo processo não pode atuar como assistente do MP.', ['Vedação depende da condição de corréu na mesma causa.', 'Não eliminar sua defesa e meios próprios de prova.'], 'Ser acusado não permite transformar-se em assistente contra o outro corréu no mesmo processo.', 'Um dos dois acusados pede assistência contra o outro e o pedido encontra vedação.', 'Continua podendo exercer defesa pelos meios legais.', ['Corréu pode assistir acusação no mesmo processo? Não.', 'A vedação retira seu direito de defesa? Não.'], 'Incompatibilidade do corréu','Impossibilidade de acumular assistência na mesma causa.')
add(271,'Assistente pode propor prova, perguntas e atuar em debates e recursos nas hipóteses legais.', ['Juiz decide provas propostas após ouvir MP.', 'Recursos próprios observam arts. 584, §1º, e 598.', 'Ausência injustificada após intimação dispensa nova intimação nos termos do §2º.', 'Remissão ao libelo é histórica: reforma do júri aboliu essa peça.'], 'Não ensinar apresentação de libelo como etapa atual nem conferir recurso universal ao assistente.', 'Assistente propõe prova e juiz decide após ouvir MP.', 'Ausência por força maior comprovada não se equipara à falta injustificada do §2º.', ['Prova proposta é deferida automaticamente? Não.', 'Libelo permanece etapa atual do júri? Não.'], 'Faculdades do assistente','Atuação subordinada às hipóteses e procedimento atuais.')
add(272,'Antes de admitir assistente, juiz ouve o Ministério Público.', ['Manifestação prévia necessária.', 'Decisão de admissão cabe ao juiz.'], 'Oitiva não significa poder absoluto de veto do MP.', 'Juiz solicita manifestação do MP antes de decidir pedido da vítima.', 'Parecer contrário é analisado, sem substituir automaticamente decisão judicial.', ['Deve ouvir MP antes? Sim.', 'Parecer é automaticamente decisão? Não.'], 'Oitiva prévia','Manifestação do MP antecedente à admissão.')
add(273,'Despacho que admite ou não assistente não tem recurso previsto pelo artigo; pedido e decisão ficam nos autos.', ['Registro formal obrigatório.', 'Distinguir recurso ordinário desta decisão de medidas autônomas em situações juridicamente cabíveis.'], 'Não afirmar imunidade total a controle judicial por ler a ausência de recurso como ausência de qualquer tutela.', 'Pedido é decidido e documentado nos autos.', 'Eventual ilegalidade demanda análise do meio adequado, sem inventar recurso ordinário previsto aqui.', ['Há recurso previsto neste artigo contra admissão? Não.', 'Pedido e decisão devem constar dos autos? Sim.'], 'Registro da admissão','Formalização de decisão sobre assistência.')
add(274,'Suspeição dos juízes se estende a serventuários e funcionários da Justiça naquilo que for aplicável.', ['Considerar função concreta e causa de suspeição.', 'Não dispensar análise por não se tratar de magistrado.'], 'Aplicação exige compatibilidade com a atividade desempenhada.', 'Servidor com vínculo legal de suspeição tem situação apreciada.', 'Não importar automaticamente hipótese incompatível com sua função.', ['Pode haver suspeição de serventuário? Sim.', 'A extensão exige compatibilidade? Sim.'], 'Auxiliar imparcial','Garantia aplicada à atuação do servidor.')
add(275,'Perito, oficial ou não, está sujeito à disciplina judiciária.', ['Nomeação não elimina controle funcional no processo.', 'Distinguir independência técnica de descumprimento de deveres.'], 'Disciplina não permite ao juiz impor conclusão científica desejada.', 'Perito cumpre prazos e procedimentos mantendo conclusão técnica fundamentada.', 'Discordância técnica não autoriza compelir laudo favorável à acusação.', ['Perito não oficial também se submete? Sim.', 'Juiz pode ditar resultado científico por disciplina? Não.'], 'Disciplina pericial','Deveres processuais sem submissão da conclusão técnica.')
add(276,'Partes não escolhem o perito nomeado pela autoridade; podem exercer direitos de participação previstos em outros artigos.', ['Integrar art. 159: quesitos e assistente técnico.', 'Nomeação oficial não elimina controle de impedimento ou suspeição.'], 'Não intervir na nomeação não significa ausência de contraditório pericial.', 'Autoridade nomeia perito e defesa apresenta quesitos cabíveis.', 'Vínculo de suspeição pode ser apontado pelo meio próprio.', ['Pode indicar assistente técnico nos termos legais? Sim.', 'A regra elimina toda impugnação? Não.'], 'Nomeação e participação','Designação pela autoridade com direitos técnicos das partes.')
add(277,'Perito nomeado aceita encargo salvo escusa atendível e justifica impedimentos imediatamente; multa em mil-réis é expressão histórica.', ['Sem justa causa: ausência ao chamado, ao exame ou atraso de laudo/realização nas hipóteses.', 'Justa causa deve ser provada imediatamente.', 'Não converter automaticamente sanção histórica em moeda atual.'], 'Não tratar recusa justificada como infração automática nem certificar valor atual com a antiga moeda.', 'Perito comprova prontamente doença impeditiva.', 'Atraso sem causa exige apreciação jurídica; não inventar conversão de mil-réis.', ['Escusa atendível pode afastar aceitação? Sim.', 'Justa causa deve ser provada imediatamente? Sim.'], 'Dever pericial','Aceitação e cumprimento sujeitos a escusa legítima.')
add(278,'Ausência injustificada do perito pode levar à condução nas condições legais.', ['Exige não comparecimento sem justa causa.', 'Preservar regular convocação e controle de necessidade.', 'Não confundir com interrogatório coercitivo de acusado.'], 'Não conduzir perito por ausência justificada; a vedação das ADPFs ao interrogatório não elimina automaticamente esta hipótese.', 'Perito regularmente convocado falta sem causa e autoridade avalia condução.', 'Doença comprovada exige análise da justificativa, não condução automática.', ['Ausência justificada basta para conduzir? Não.', 'É hipótese diferente do interrogatório do réu? Sim.'], 'Comparecimento pericial','Presença do auxiliar sob condições legais.',[ADPF])
add(279,'O artigo enumera impedimentos periciais, mas conserva remissão ao antigo Código Penal e referência etária histórica que exigem leitura integrada.', ['Quem depôs no processo ou opinou antes sobre objeto da perícia é abrangido pelo inciso II.', 'Inciso I remete a antiga estrutura do CP: não usar números como se fossem atuais.', 'Inciso III ainda diz analfabetos e menores de 21 no compilado; distinguir literalidade de integração com capacidade civil aos 18.', 'Qualificação pericial atual também segue art. 159.'], 'Não declarar automaticamente uma perícia inválida só por idade de 18 a 20, nem anunciar revogação textual inexistente. A interação da cláusula histórica com maioridade civil exige análise específica, não flashcard universal.', 'Pessoa que já depôs como testemunha sobre o fato não é escolhida para perícia naquele objeto.', 'Sobre idade e remissão antiga, consultar regime integrado e qualificação, sem resposta automática baseada só no número 21.', ['Quem depôs pode ignorar o impedimento do inciso II? Não.', 'O número do antigo CP deve ser transportado sem atualização? Não.'], 'Impedimento pericial','Restrições com leitura integrada das redações históricas.',[CC])
add(280,'Regras de suspeição do juiz aplicam-se aos peritos quando compatíveis.', ['Analisar vínculo concreto com partes e objeto.', 'Distinguir suspeição de discordância com resultado técnico.'], 'Laudo desfavorável não demonstra sozinho suspeição.', 'Perito credor de parte tem vínculo examinado pela regra aplicável.', 'Resultado desfavorável fundamentado exige crítica técnica, não acusação automática de parcialidade.', ['Suspeição pode alcançar perito? Sim.', 'Discordância do laudo prova sozinha suspeição? Não.'], 'Perícia imparcial','Ausência de vínculos que comprometam atuação técnica.')
add(281,'Intérpretes equiparam-se a peritos para efeitos legais pertinentes.', ['Deveres e causas de afastamento aplicáveis.', 'Interpretação deve preservar sentido e acessibilidade.', 'Equiparação não transforma intérprete em testemunha dos fatos.'], 'Não permitir tradução dirigida a favorecer parte; integrar regras especiais de acessibilidade.', 'Intérprete fielmente transmite perguntas e respostas, observando deveres e afastamentos.', 'Alterar sentido para beneficiar interessado compromete a função, ainda que chamado apenas de tradutor.', ['Equiparação alcança deveres aplicáveis? Sim.', 'Pode alterar sentido para ajudar parte? Não.'], 'Intérprete processual','Auxiliar de comunicação sujeito a garantias técnicas.')
assert len(rows)==31
Path(sys.argv[1]).write_text(json.dumps({'course_slug':'codigo-processo-penal','units':rows},ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(len(rows),'participants reviewed')
